import { test } from 'node:test'
import assert from 'node:assert/strict'
import {
  countLines, differing, levels, parseCoverage, parseFindings, parseSemver, readmeMismatches, testCount,
} from '../../scripts/site-facts.js'

test('site facts: coverage header and resource rows', () => {
  const md = [
    'Generated by `npx tsx conformance/coverage.ts` from Minka\'s published OpenAPI spec (2.47.2).',
    '',
    '**3 of 4** operations implemented; 2 of them confirmed by a recorded reference exchange.',
    '',
    '| Resource | Implemented | Operations |',
    '| --- | --- | --- |',
    '| signers | 2/3 | `POST /signers/{id}/access/\\!check` ✓ |',
    '| oauth | 1/1 | `POST /oauth/token` ✓ |',
  ].join('\n')
  assert.deepEqual(parseCoverage(md), {
    operations: { total: 4, implemented: 3, confirmed: 2, spec: '2.47.2' },
    resources: [{ name: 'signers', implemented: 2, total: 3 }, { name: 'oauth', implemented: 1, total: 1 }],
  })
  assert.throws(() => parseCoverage(md.replace('| oauth | 1/1', '| oauth | 1/2')), /add up to 5/)
  assert.throws(() => parseCoverage('nothing'), /header/)
})

test('site facts: findings count only dated headings, outside code too', () => {
  const md = '## 2026-10-24 — b\n```\n## not a section\n```\n## Notes\n## 2026-09-26 — a\n'
  assert.deepEqual(parseFindings(md), { sections: 2, firstDate: '2026-09-26', lastDate: '2026-10-24' })
  assert.throws(() => parseFindings('# none'), /no dated/)
})

test('site facts: lines, test log and SEMVER', () => {
  assert.equal(countLines('{}\n{}\n\n'), 2)
  assert.equal(countLines(''), 0)
  assert.equal(testCount('ℹ suites 3\nℹ tests 446\nℹ pass 446\n'), 446)
  assert.throws(() => testCount('✖ crashed'), /no "ℹ tests N"/)
  assert.equal(parseSemver("export const SEMVER = '2.47.9'\n"), '2.47.9')
})

test('site facts: levels subtract listed divergences, client and bridge apart', () => {
  const divs = [
    { fixture: 'l3', exchanges: [35, 40] },
    { fixture: 'l7', exchanges: [1] },
    { fixture: 'l7.bridge.jsonl', exchanges: [2, 3] },
  ]
  assert.equal(differing(divs, 'l7', false), 1)
  assert.equal(differing(divs, 'l7', true), 2)
  const sizes: Record<string, number> = {
    'l0.reference.jsonl': 18, 'l1.reference.jsonl': 30, 'l3.reference.jsonl': 41,
    'l7.reference.jsonl': 36, 'l7.bridge.jsonl': 12,
  }
  const all = levels((f) => sizes[f] ?? (f.endsWith('.reference.jsonl') ? 5 : null), divs)
  assert.deepEqual(all.find((l) => l.id === 'L3')!.fixtures, [
    { name: 'l3', clientTotal: 41, clientMatched: 39, bridgeTotal: 0, bridgeMatched: 0, differ: 2 },
  ])
  assert.deepEqual(all.find((l) => l.id === 'L7')!.fixtures[0], {
    name: 'l7', clientTotal: 36, clientMatched: 35, bridgeTotal: 12, bridgeMatched: 10, differ: 3,
  })
  assert.throws(() => levels(() => null, divs), /no fixture l0\.reference\.jsonl/)
})

test('site facts: README prose must agree', () => {
  const facts = { tests: { postgres: 446 }, divergences: { count: 21, fixtures: 14 } } as never
  const ok = 'tests (`server/test/`, 446 with Postgres) … So far: 21 cases in 14 fixtures'
  assert.deepEqual(readmeMismatches(ok, facts), [])
  assert.equal(readmeMismatches(ok.replace('446', '217').replace('21 cases', 'one'), facts).length, 2)
})
